package toolset
import("context";"encoding/json";"os";"path/filepath";"strings";"testing";"time")
func TestAuditFinalErrorPaths(t *testing.T){base:=t.TempDir();ws:=filepath.Join(base,"workspace");if err:=os.MkdirAll(ws,0700);err!=nil{t.Fatal(err)};set,err:=New(Options{Workspace:ws,Policy:PolicyWorkspace,SessionID:"audit-path"});if err!=nil{t.Fatal(err)};t.Run("quoted_outside_space",func(t *testing.T){p:=filepath.Join(base,"outside private","secret-dir","key.txt");got:=set.sanitizeErrorText("open "+strconvQuote(p)+": denied");t.Logf("sanitized=%q",got);if strings.Contains(got,"secret-dir"){t.Error("outside directory tail leaked")}});t.Run("lsp_error",func(t *testing.T){p:=filepath.Join(ws,"missing.go");r:=set.lspFailure(context.Background(),"lsp_rename",&os.PathError{Op:"lstat",Path:p,Err:os.ErrNotExist},time.Now());var v map[string]any;if err:=json.Unmarshal([]byte(r.Content),&v);err!=nil{t.Fatal(err)};t.Logf("lsp=%s",r.Content);if strings.Contains(r.Content,base){t.Error("new LSP error leaks absolute host path")}})}
func strconvQuote(s string)string{b,_:=json.Marshal(s);return string(b)}
